// Full chapter-body copy. Keep the chapter IDs aligned with HowToPlayModal.tsx.
export const howToPlayTranslations: GuideCopy = {
  fr: {
    start: { title: '1. Commencer ici : découvrir l’écran d’accueil', intro: 'L’écran d’accueil est votre tableau de bord. Faites défiler vers le haut et vers le bas pour voir toute la page.', steps: ['Votre solde Street Coins apparaît en haut. Touchez-le ou son raccourci pour consulter vos opérations.', 'Utilisez Quick Hustle Hub et la navigation inférieure pour ouvrir les différentes parties de Street Life.', 'HOME ouvre l’accueil, GAMES la bibliothèque de jeux, STUDIO les outils freestyle, SHOP les articles et améliorations, TOUGH WAR la zone de combat et PROFILE vos informations et réglages.', 'Les raccourcis peuvent aussi ouvrir TASKS, WATCH & EARN, BANK et l’inventaire. Lisez le titre de chaque écran.', 'Si une page semble coupée, faites défiler son contenu. Sur les écrans compatibles, le bouton en forme d’œil masque ou affiche les barres de navigation.'] },
    games: { title: '2. Choisir un jeu et comprendre les modes', intro: 'Ouvrez GAMES dans la navigation inférieure. Choisissez une catégorie, puis touchez la carte du jeu souhaité.', steps: ['Street Gang Star : ouvrez le hub du jeu et choisissez Single Player ou Multiplayer. En multijoueur, créez une salle avec code, rejoignez-en une avec un code ou utilisez Random City Match si disponible.', 'Street Race : choisissez une course, lisez les consignes et utilisez les commandes de conduite affichées. Évitez la circulation et les obstacles et ramassez les pièces disponibles.', 'Street Rider Delivery : suivez l’objectif de livraison et le chronomètre. Utilisez les commandes de la moto pour atteindre la destination.', 'Street Dice : choisissez Single Player ou Multiplayer. L’hôte crée une salle et partage son code ; les autres joueurs saisissent ce code pour la rejoindre.', 'Les autres mini-jeux peuvent inclure Turf War, Street Crush, Street Slot et Street Flip. Chaque jeu possède ses propres règles et commandes.', 'Les jeux indiqués Coming Soon ne sont pas encore jouables.', 'Utilisez Back dans le jeu pour revenir à la liste. Évitez de fermer Telegram pendant une partie.'] },
    multiplayer: { title: '3. Multijoueur : créer une salle et inviter des amis', intro: 'Le salon varie selon le jeu. Suivez les commandes affichées dans le jeu choisi.', steps: ['Ouvrez GAMES, choisissez un jeu compatible et touchez Multiplayer. Dans Street Gang Star, ouvrez d’abord le hub du jeu.', 'Pour héberger une salle privée, touchez Create Room et attendez. Le code apparaît dans le salon ou l’en-tête du jeu.', 'Copiez le code si le bouton est disponible et envoyez-le intégralement à votre ami sur Telegram. Vérifiez qu’il correspond au bon jeu.', 'Votre ami doit ouvrir le même jeu, choisir Multiplayer, saisir ou coller le code dans Join puis toucher JOIN. Supprimez les espaces accidentels.', 'Dans Street Dice, l’hôte voit les participants et peut parfois ajouter un joueur IA. Les joueurs touchent Ready si disponible ; l’hôte lance la partie lorsque tous sont prêts.', 'Dans Street Gang Star, les amis rejoignent la salle privée avec le code exact. Random City Match est une autre option.', 'Attendez la confirmation ou l’apparition de l’autre joueur dans le salon. Envoyer le code ne signifie pas qu’il a rejoint la salle.', 'Si la salle est pleine, expirée ou terminée, créez-en une nouvelle et partagez le nouveau code.'] },
    rejoin: { title: '4. Déconnexion, échec de connexion et retour dans une salle', intro: 'Un code ne garantit pas que la salle restera disponible. Le retour dépend du jeu et de l’activité de la salle.', steps: ['Vérifiez votre connexion Internet, puis rouvrez le même jeu et son écran Multiplayer.', 'Si Rejoin ou Continue apparaît, utilisez cette option. Street Dice peut conserver les informations de la salle sur l’appareil et restaurer la session.', 'Si la salle ne revient pas, demandez à l’hôte si elle est toujours ouverte et réclamez le code actuel.', 'Si le code est refusé, vérifiez les lettres et chiffres, le jeu choisi et demandez si la salle est pleine ou terminée.', 'Si l’hôte est parti ou si la salle est fermée, créez une nouvelle salle et invitez de nouveau les joueurs.', 'Si l’écran se bloque, attendez, utilisez Back puis rouvrez le mode. Si nécessaire, fermez et relancez le Mini App Telegram.', 'Ne touchez pas plusieurs fois à Create Room pendant le traitement de la première demande.'] },
    controls: { title: '5. Commandes, objectifs et fin d’une partie', intro: 'Les commandes dépendent du jeu et de l’appareil. Lisez les indications affichées avant de commencer.', steps: ['Sur téléphone, utilisez le joystick virtuel, les flèches ou les boutons d’action. Relâchez votre doigt pour arrêter.', 'Dans Street Gang Star, le joystick déplace le personnage. Utilisez les boutons disponibles pour tirer, sauter, recharger, vous mettre à couvert, courir ou conduire.', 'Dans les jeux de course et de moto, utilisez les commandes pour tourner, accélérer et freiner. Suivez l’objectif et le chronomètre.', 'Dans Street Dice, lancez les dés à votre tour et choisissez un pion lorsque le jeu autorise le déplacement.', 'Lisez les règles propres aux autres mini-jeux. Les commandes d’un jeu ne fonctionnent pas nécessairement dans un autre.', 'À la fin, lisez le résultat et le message de récompense. Si elle n’apparaît pas, vérifiez le solde et l’historique avant de recommencer.'] },
    coins: { title: '6. Street Coins, récompenses et activités quotidiennes', intro: 'Les Street Coins sont la monnaie virtuelle du jeu. Les conditions et montants dépendent de chaque activité.', steps: ['Consultez votre solde sur Home et ouvrez l’historique des transactions pour voir les opérations enregistrées.', 'Ouvrez WATCH & EARN, touchez le bouton de visionnage et laissez la vidéo sponsorisée se terminer. Une publicité ignorée, indisponible ou en échec ne donne pas droit à la récompense.', 'Les récompenses quotidiennes et les tâches ont leurs propres conditions. Lisez-les et vérifiez le statut avant de toucher Claim.', 'Certaines activités ont des limites quotidiennes, des délais d’attente ou des conditions d’éligibilité. Consultez le message affiché.', 'Ne supposez pas que chaque jeu, vidéo, tâche ou publication Studio rapporte des pièces. Fiez-vous uniquement à la confirmation de l’application.'] },
    tasks: { title: '7. TASKS : terminer une activité et l’envoyer en vérification', intro: 'Certaines tâches exigent une action hors du jeu puis l’envoi de preuves. Réaliser l’activité et envoyer la preuve sont deux étapes distinctes.', steps: ['Ouvrez TASKS depuis Home ou Quick Hustle Hub. Lisez les instructions complètes, la récompense, les limites et les preuves exigées.', 'Touchez le bouton de la tâche et réalisez l’action demandée : rejoindre le canal ou groupe officiel, suivre un compte, inviter un ami, atteindre un objectif ou publier une promotion.', 'Revenez à la même tâche. Préparez exactement les preuves demandées : capture nette de l’action terminée et, pour une vidéo, lien public et captures des vues ou mentions J’aime si demandées.', 'Si une étape de préparation est prévue, touchez le bouton correspondant. Il peut ensuite devenir Submit for review.', 'Touchez Submit for review une seule fois et attendez la confirmation. Ne touchez pas plusieurs fois pendant l’envoi.', 'Pour la tâche de statut, téléversez d’abord la capture de la publication puis envoyez la preuve. Respectez la limite quotidienne indiquée.', 'Pour la promotion vidéo, utilisez uniquement les plateformes acceptées dans les consignes, par exemple TikTok, YouTube ou Facebook. Envoyez le lien et les captures demandées.', 'Pending Review signifie que la vérification est en cours. Approved ou Verified signifie accepté. Rejected signifie refusé : lisez le motif et corrigez la preuve si possible.', 'Ne soumettez pas plusieurs fois une tâche en attente. Certaines récompenses sont créditées après vérification du serveur et approbation.'] },
    studio: { title: '8. STUDIO : enregistrer un freestyle audio', intro: 'Studio permet de choisir une instru, enregistrer votre voix, écouter le mix et le publier. Certaines fonctions exigent une location active ou un niveau débloqué.', steps: ['Ouvrez STUDIO dans la navigation inférieure. Vérifiez que votre accès ou location Studio est actif.', 'Parcourez les instrus, touchez-en une puis utilisez Preview ou Play pour l’écouter. Certaines instrus exigent un niveau supérieur.', 'Réglez Beat Volume et Voice Volume pour équilibrer séparément la musique et votre voix.', 'Autorisez l’accès au microphone lorsque le téléphone le demande. Si vous refusez, l’enregistrement peut échouer ; activez l’autorisation dans les réglages de l’appareil ou du navigateur.', 'Touchez Record et enregistrez votre freestyle en respectant la durée minimale et maximale affichée. Touchez Stop pour terminer.', 'Touchez Preview Mix pour écouter. Si le résultat ne vous plaît pas, recommencez si vous avez encore des enregistrements disponibles.', 'Lorsque le mix vous convient, touchez Post Mix ou Post et attendez le message de réussite ou d’erreur.', 'Les limites quotidiennes peuvent être partagées entre les enregistrements audio et vidéo et dépendre du niveau Studio. Vérifiez le compteur.'] },
    video: { title: '9. STUDIO : enregistrer un freestyle vidéo', intro: 'Video Freestyle utilise la caméra du téléphone. Telegram doit avoir accès à la caméra et au microphone.', steps: ['Ouvrez STUDIO puis Video Freestyle. Touchez Enable Camera lorsque cela est demandé.', 'Si iPhone ou Telegram demande l’accès à la caméra ou au microphone, choisissez Allow. Si l’accès a été bloqué, modifiez l’autorisation dans les réglages de l’appareil.', 'Utilisez Flip pour passer de la caméra avant à la caméra arrière si votre appareil le permet. Le changement peut être indisponible pendant l’enregistrement.', 'Choisissez un filtre : Normal, Warm, B&W, Cool ou Vintage. Faites défiler l’écran pour voir toutes les commandes ; les boutons d’action se trouvent au-dessus des filtres.', 'Touchez Record pour commencer, Stop pour terminer et Preview pour regarder la vidéo avant publication.', 'Touchez Post lorsque le résultat vous convient et attendez la confirmation. En cas d’échec, vérifiez la connexion.', 'Touchez Close pour quitter. Ne fermez pas la caméra pendant un enregistrement.'] },
    shop: { title: '10. SHOP, inventaire, améliorations et articles', intro: 'Ouvrez SHOP dans la navigation inférieure pour consulter les articles et améliorations. Les catégories peuvent inclure vêtements, maisons, véhicules, téléphones, nourriture et Studio.', steps: ['Choisissez une catégorie puis un article pour voir sa description et son prix. Vérifiez le coût en Street Coins avant l’achat.', 'Touchez Buy ou le bouton d’achat et attendez la confirmation. Ne touchez pas plusieurs fois pendant la mise à jour du solde.', 'Les articles achetés peuvent être équipés depuis leur fiche ou l’inventaire. Posséder un article ne signifie pas qu’il est équipé : choisissez Equip.', 'Certains articles sont consommables, loués, permanents ou constituent des améliorations. Lisez la description et la durée de validité.', 'Si votre solde est insuffisant, gagnez des Street Coins avec des activités éligibles ou choisissez un article moins cher.'] },
    bank: { title: '11. BANK, portefeuille, conversions et retraits', intro: 'BANK peut afficher le solde, le convertisseur, les retraits, l’historique et d’autres rubriques. Les conditions peuvent changer.', steps: ['Ouvrez BANK depuis les raccourcis Home. Utilisez les onglets pour consulter le solde, le convertisseur, les retraits et l’historique.', 'Avant une conversion, vérifiez la devise, le taux et le montant affichés dans la confirmation.', 'Avant une demande de retrait, lisez le montant minimum, la méthode acceptée, le réseau, les instructions d’adresse, la date de disponibilité et le statut.', 'Saisissez uniquement une adresse qui vous appartient et correspond au réseau ou à la méthode sélectionnée. Une mauvaise adresse ou un mauvais réseau peut entraîner une perte de fonds.', 'Une demande envoyée n’est pas un paiement terminé. Consultez l’historique et le statut ; une demande en attente ne signifie pas que l’argent a été reçu.'] },
    profile: { title: '12. PROFILE, invitations, langue et assistance', intro: 'Votre profil affiche votre identité Telegram, vos informations de joueur, les réglages et les options d’aide.', steps: ['Ouvrez PROFILE dans la navigation inférieure. Vérifiez que le nom Telegram et les informations affichées sont les vôtres.', 'Utilisez le code d’invitation ou le lien de parrainage pour copier votre invitation personnelle et la partager avec un ami.', 'Ouvrez Settings pour modifier les préférences disponibles, notamment la langue. Choisissez Français pour afficher les traductions disponibles.', 'Utilisez Support si vous avez besoin d’aide. Indiquez l’écran, le bouton utilisé, ce que vous attendiez et ce qui s’est produit.', 'Protégez votre compte Telegram. Ne partagez jamais vos codes de connexion, mots de passe, clés privées ou phrase de récupération du portefeuille.'] },
    troubleshoot: { title: '13. Problèmes courants et solutions', intro: 'Essayez ces étapes avant de répéter un achat, un envoi ou une action de salle.', steps: ['Un bouton ne répond pas : attendez quelques secondes, vérifiez la connexion, faites défiler pour afficher entièrement le bouton puis réessayez une fois.', 'Un jeu ne charge pas : revenez à GAMES, rouvrez-le et, si nécessaire, fermez puis relancez le Mini App Telegram.', 'Un ami ne peut pas rejoindre : vérifiez que vous avez ouvert le même jeu, contrôlez chaque caractère du code et demandez à l’hôte si la salle est active.', 'Une salle a été perdue : utilisez Rejoin si disponible. Sinon, demandez le code actuel à l’hôte ou créez une nouvelle salle.', 'La caméra ou le microphone ne fonctionne pas : vérifiez les autorisations Telegram/iPhone, fermez les autres applications utilisant la caméra puis rouvrez Studio.', 'Une tâche est en attente : patientez et consultez son statut plus tard. N’envoyez pas de doublon.', 'Une récompense ou un achat est incertain : vérifiez le solde et l’historique puis contactez Support avec le nom de l’écran et l’heure approximative. Ne communiquez aucun secret.'] },
    fairplay: { title: '14. Jouer loyalement et protéger son compte', intro: 'Contribuez à rendre Street Life agréable et protégez votre progression.', steps: ['Ne trichez pas, n’exploitez pas les bugs, ne vous faites pas passer pour un autre joueur et ne harcelez personne.', 'Partagez les codes de salle uniquement avec les personnes invitées. Ne publiez pas d’informations privées dans les discussions publiques.', 'Suivez uniquement les instructions officielles de l’application pour les récompenses, tâches et paiements. Personne ne doit demander votre code Telegram ou votre phrase de récupération.', 'Si quelque chose semble anormal, arrêtez et contactez Support au lieu d’exploiter le problème.'] }
  },
  es: {
    start: { title: '1. Empieza aquí: conoce la pantalla de inicio', intro: 'La pantalla de inicio es tu panel principal. Desliza hacia arriba y abajo para ver toda la página.', steps: ['Tu saldo de Street Coins aparece arriba. Tócalo o usa su acceso directo para revisar las transacciones.', 'Usa Quick Hustle Hub y la navegación inferior para abrir las distintas secciones de Street Life.', 'HOME vuelve al inicio; GAMES abre los juegos; STUDIO abre las herramientas freestyle; SHOP muestra artículos y mejoras; TOUGH WAR abre la zona de combate; PROFILE contiene tus datos y ajustes.', 'Otros accesos pueden abrir TASKS, WATCH & EARN, BANK y el inventario. Lee el título de cada pantalla.', 'Si una pantalla parece cortada, desplázate dentro de la página. En pantallas compatibles, el botón del ojo oculta o muestra las barras de navegación.'] },
    games: { title: '2. Elige un juego y conoce sus modos', intro: 'Abre GAMES en la navegación inferior. Elige una categoría y toca la tarjeta del juego.', steps: ['Street Gang Star: abre el centro del juego y elige Single Player o Multiplayer. En multijugador puedes crear una sala con código, entrar con un código o usar Random City Match si está disponible.', 'Street Race: elige una carrera, lee las instrucciones y usa los controles de conducción. Evita el tráfico y los obstáculos y recoge monedas cuando estén disponibles.', 'Street Rider Delivery: sigue el objetivo de entrega y el temporizador. Usa los controles de la moto para llegar al destino.', 'Street Dice: elige Single Player o Multiplayer. El anfitrión crea una sala y comparte el código; los demás lo introducen para entrar.', 'Otros minijuegos pueden incluir Turf War, Street Crush, Street Slot y Street Flip. Cada juego tiene reglas y controles propios.', 'Los juegos que indiquen Coming Soon todavía no se pueden jugar.', 'Usa Back dentro del juego para volver a la lista. Evita cerrar Telegram durante una partida.'] },
    multiplayer: { title: '3. Multijugador: crea una sala e invita a tus amigos', intro: 'La sala puede variar según el juego. Sigue los controles que aparecen en el juego elegido.', steps: ['Abre GAMES, elige un juego compatible y toca Multiplayer. En Street Gang Star, abre primero el centro del juego.', 'Para crear una sala privada, toca Create Room y espera. El código aparecerá en la sala o en el encabezado.', 'Copia el código si aparece esa opción y envíalo completo a tu amigo por Telegram. Comprueba que sea del juego correcto.', 'Tu amigo debe abrir el mismo juego, elegir Multiplayer, escribir o pegar el código en Join y tocar JOIN. Elimina espacios accidentales.', 'En Street Dice, el anfitrión puede ver a los participantes y, si está disponible, añadir un jugador de IA. Los jugadores pulsan Ready y el anfitrión inicia cuando todos estén listos.', 'En Street Gang Star, los amigos entran en la sala privada con el código exacto. Random City Match es una opción distinta.', 'Espera la confirmación o que aparezca el otro jugador en la sala. Enviar el código no significa que ya haya entrado.', 'Si la sala está llena, caducó o terminó, crea otra y comparte el nuevo código.'] },
    rejoin: { title: '4. Desconexiones y cómo volver a una sala', intro: 'Un código no garantiza que la sala siga disponible. Volver depende del juego y de que la sala continúe activa.', steps: ['Comprueba tu conexión a Internet y vuelve al mismo juego y a Multiplayer.', 'Si aparece Rejoin o Continue, úsalo. Street Dice puede guardar información de la sala en el dispositivo y restaurarla al volver.', 'Si no se restaura, pregunta al anfitrión si la sala sigue abierta y pide el código actual.', 'Si rechaza el código, revisa letras y números, confirma que elegiste el mismo juego y pregunta si la sala está llena o terminó.', 'Si el anfitrión salió o la sala se cerró, crea una nueva e invita otra vez a los jugadores.', 'Si la pantalla se bloquea, espera, pulsa Back y vuelve a abrir el modo. Si continúa, cierra y abre de nuevo el Mini App de Telegram.', 'No pulses Create Room repetidamente mientras se procesa la primera solicitud.'] },
    controls: { title: '5. Controles, objetivos y final de la partida', intro: 'Los controles dependen del juego y del dispositivo. Lee las indicaciones antes de empezar.', steps: ['En el móvil usa el joystick virtual, las flechas o los botones de acción. Suelta el dedo para detenerte.', 'En Street Gang Star, el joystick mueve al personaje. Usa los botones disponibles para disparar, saltar, recargar, cubrirte, correr o conducir.', 'En carreras y motos, usa los controles para girar, acelerar y frenar. Sigue el objetivo y el temporizador.', 'En Street Dice, tira los dados por turnos y selecciona una ficha cuando el juego permita moverla.', 'Lee las reglas de cada minijuego. Los controles de un juego pueden no servir en otro.', 'Al terminar, lee el resultado y la recompensa. Si no aparece, revisa el saldo y el historial antes de repetir la acción.'] },
    coins: { title: '6. Street Coins, recompensas y actividades diarias', intro: 'Street Coins es la moneda virtual del juego. Los requisitos y cantidades dependen de cada actividad.', steps: ['Consulta tu saldo en Home y abre el historial para revisar las transacciones registradas.', 'Abre WATCH & EARN, toca el botón para ver y deja terminar el vídeo patrocinado. Un anuncio omitido, fallido o no disponible no genera recompensa.', 'Las recompensas diarias y las tareas tienen requisitos propios. Léelos y revisa el estado antes de tocar Claim.', 'Algunas actividades tienen límites diarios, tiempos de espera o requisitos de elegibilidad. Consulta el mensaje en pantalla.', 'No supongas que todos los juegos, vídeos, tareas o publicaciones de Studio pagan monedas. Confía solo en las recompensas confirmadas por la app.'] },
    tasks: { title: '7. TASKS: completa actividades y envíalas a revisión', intro: 'Algunas tareas requieren hacer algo fuera del juego y enviar pruebas. Completar la actividad y enviar la prueba son pasos distintos.', steps: ['Abre TASKS desde Home o Quick Hustle Hub. Lee las instrucciones completas, la recompensa, los límites y las pruebas necesarias.', 'Pulsa el botón de la tarea y realiza la actividad solicitada: unirte al canal o grupo oficial, seguir una cuenta, invitar a un amigo, alcanzar un objetivo o publicar una promoción.', 'Vuelve a la misma tarea. Prepara exactamente las pruebas solicitadas: una captura clara de la acción y, para vídeos, el enlace público y capturas de visitas o me gusta si se piden.', 'Si hay un paso de preparación, pulsa el botón indicado. Después puede cambiar a Submit for review.', 'Pulsa Submit for review una sola vez y espera la confirmación. No pulses repetidamente mientras se procesa.', 'Para la tarea de estado, sube primero la captura de la publicación y después envía la prueba. Respeta el límite diario.', 'Para promocionar vídeos, usa solo las plataformas aceptadas en las instrucciones, como TikTok, YouTube o Facebook. Envía el enlace y las capturas requeridas.', 'Pending Review significa que sigue en revisión. Approved o Verified significa aceptada. Rejected significa rechazada: lee el motivo y corrige la prueba si se permite.', 'No envíes la misma tarea varias veces mientras esté pendiente. Algunas recompensas se acreditan tras la verificación y aprobación.'] },
    studio: { title: '8. STUDIO: graba un freestyle de audio', intro: 'Studio permite elegir una base, grabar tu voz, escuchar la mezcla y publicarla. Algunas funciones requieren alquiler activo o un nivel desbloqueado.', steps: ['Abre STUDIO en la navegación inferior. Comprueba que el acceso o alquiler de Studio esté activo.', 'Explora las bases, toca una para seleccionarla y usa Preview o Play para escucharla. Algunas requieren un nivel superior.', 'Ajusta Beat Volume y Voice Volume para equilibrar la música y tu voz.', 'Permite el acceso al micrófono cuando el teléfono lo solicite. Si lo deniegas, la grabación puede fallar; activa el permiso en los ajustes del dispositivo o navegador.', 'Pulsa Record y graba tu freestyle respetando la duración mínima y máxima indicada. Pulsa Stop al terminar.', 'Pulsa Preview Mix para escuchar. Si no te gusta, vuelve a grabar si aún tienes grabaciones disponibles.', 'Cuando estés satisfecho, pulsa Post Mix o Post y espera el mensaje de éxito o error.', 'Los límites diarios pueden compartirse entre audio y vídeo y depender del nivel de Studio. Comprueba el contador.'] },
    video: { title: '9. STUDIO: graba un freestyle de vídeo', intro: 'Video Freestyle utiliza la cámara del teléfono. Telegram necesita permiso para la cámara y el micrófono.', steps: ['Abre STUDIO y entra en Video Freestyle. Pulsa Enable Camera cuando se solicite.', 'Si iPhone o Telegram pide permiso para la cámara o el micrófono, elige Allow. Si lo bloqueaste antes, cambia el permiso en los ajustes del dispositivo.', 'Usa Flip para cambiar entre la cámara frontal y trasera si el dispositivo lo permite. Puede no estar disponible durante la grabación.', 'Elige un filtro: Normal, Warm, B&W, Cool o Vintage. Desplázate por la pantalla para ver todos los controles; los botones de acción están encima de los filtros.', 'Pulsa Record para empezar y Stop para terminar. Usa Preview para ver el vídeo antes de publicarlo.', 'Pulsa Post cuando estés satisfecho y espera la confirmación. Si falla la subida, comprueba la conexión.', 'Pulsa Close para salir. No cierres la cámara mientras grabas.'] },
    shop: { title: '10. SHOP, inventario, mejoras y artículos', intro: 'Abre SHOP en la navegación inferior para ver artículos y mejoras. Puede incluir ropa, casas, vehículos, teléfonos, comida y mejoras de Studio.', steps: ['Elige una categoría y un artículo para ver detalles y precio. Comprueba el coste en Street Coins antes de comprar.', 'Pulsa Buy o el botón de compra y espera la confirmación. No pulses varias veces mientras se actualiza el saldo.', 'Puedes equipar artículos desde su tarjeta o el inventario. Tener un artículo no significa que esté equipado: elige Equip.', 'Algunos artículos son consumibles, alquileres, permanentes o mejoras. Lee la descripción y la fecha de caducidad.', 'Si no tienes saldo suficiente, consigue Street Coins mediante actividades válidas o elige un artículo más barato.'] },
    bank: { title: '11. BANK, cartera, conversiones y retiros', intro: 'BANK puede mostrar saldo, conversor, retiros, historial y otras secciones. Los requisitos pueden cambiar.', steps: ['Abre BANK desde los accesos de Home. Usa las pestañas para consultar saldo, conversor, retiros e historial.', 'Antes de convertir monedas, comprueba la moneda, el tipo de cambio y la cantidad mostrada en la confirmación.', 'Antes de solicitar un retiro, lee el mínimo, método admitido, red, instrucciones de dirección, fecha disponible y estado.', 'Introduce solo una dirección que te pertenezca y coincida con la red o método seleccionado. Una dirección o red incorrecta puede causar pérdida de fondos.', 'Enviar una solicitud no significa que el pago esté completo. Consulta el historial y el estado; una solicitud pendiente no es dinero recibido.'] },
    profile: { title: '12. PROFILE, invitaciones, idioma y soporte', intro: 'Tu perfil muestra tu identidad de Telegram, información del jugador, ajustes y opciones de ayuda.', steps: ['Abre PROFILE en la navegación inferior. Comprueba que el nombre y los datos de Telegram sean tuyos.', 'Usa el código de invitación o enlace de referido para copiar tu invitación personal y compartirla.', 'Abre Settings para cambiar las preferencias disponibles, incluido el idioma. Elige Español para ver las traducciones disponibles.', 'Usa Support si necesitas ayuda. Explica qué pantalla y botón utilizaste, qué esperabas y qué ocurrió.', 'Protege tu cuenta de Telegram. No compartas códigos de acceso, contraseñas, claves privadas ni frases de recuperación.'] },
    troubleshoot: { title: '13. Problemas frecuentes y soluciones', intro: 'Prueba estos pasos antes de repetir una compra, envío o acción de sala.', steps: ['Un botón no responde: espera unos segundos, comprueba la conexión, desplázate para mostrarlo completo e inténtalo una vez más.', 'Un juego no carga: vuelve a GAMES, ábrelo otra vez y, si hace falta, cierra y abre el Mini App de Telegram.', 'Un amigo no puede entrar: confirma que ambos abrieron el mismo juego, revisa cada carácter del código y pregunta al anfitrión si la sala sigue activa.', 'Se perdió una sala: usa Rejoin si aparece. Si no, pide el código actual o crea una sala nueva.', 'La cámara o el micrófono no funcionan: revisa los permisos de Telegram/iPhone, cierra otras apps que usen la cámara y vuelve a abrir Studio.', 'Una tarea está pendiente: espera la revisión y consulta el estado más tarde. No envíes duplicados.', 'Una recompensa o compra no está clara: revisa el saldo y el historial y contacta con Support indicando la pantalla y la hora aproximada. Nunca compartas secretos.'] },
    fairplay: { title: '14. Juega limpio y protege tu cuenta', intro: 'Ayuda a que Street Life sea divertido y protege tu progreso.', steps: ['No hagas trampas, no explotes errores, no suplantes a otros jugadores ni acoses a nadie.', 'Comparte los códigos de sala solo con las personas invitadas. No publiques información privada en chats públicos.', 'Sigue únicamente las instrucciones oficiales de la app para recompensas, tareas y pagos. Nadie debe pedirte el código de acceso de Telegram ni la frase de recuperación de tu cartera.', 'Si algo parece incorrecto, detente y contacta con Support en lugar de intentar aprovechar el problema.'] }
  },
  ru: {
    start: { title: '1. Начало: главный экран', intro: 'Главный экран — ваша панель управления. Прокручивайте страницу вверх и вниз, чтобы увидеть всё содержимое.', steps: ['Баланс Street Coins показан вверху. Нажмите на него или ярлык операций, чтобы посмотреть историю.', 'Используйте Quick Hustle Hub и нижнюю панель навигации для перехода между разделами Street Life.', 'HOME открывает главную страницу, GAMES — игры, STUDIO — инструменты freestyle, SHOP — предметы и улучшения, TOUGH WAR — боевой раздел, PROFILE — данные и настройки игрока.', 'Другие ярлыки открывают TASKS, WATCH & EARN, BANK и инвентарь. Проверяйте заголовок каждого экрана.', 'Если экран отображается не полностью, прокрутите страницу. На поддерживаемых экранах кнопка с глазом скрывает или показывает панели навигации.'] },
    games: { title: '2. Выбор игры и режимы', intro: 'Откройте GAMES на нижней панели. Выберите категорию, затем карточку нужной игры.', steps: ['Street Gang Star: откройте игровой центр и выберите Single Player или Multiplayer. В сетевой игре создайте комнату с кодом, войдите по коду или используйте Random City Match, если доступно.', 'Street Race: выберите гонку, прочитайте инструкции и используйте экранные элементы управления. Избегайте машин и препятствий, собирайте монеты, если они доступны.', 'Street Rider Delivery: следуйте цели доставки и таймеру. Управляйте мотоциклом, чтобы добраться до пункта назначения.', 'Street Dice: выберите Single Player или Multiplayer. Хозяин создаёт комнату и отправляет код; остальные вводят его для входа.', 'Другие мини-игры могут включать Turf War, Street Crush, Street Slot и Street Flip. У каждой игры свои правила и управление.', 'Игры с пометкой Coming Soon пока недоступны.', 'Используйте Back внутри игры, чтобы вернуться к списку. Не закрывайте Telegram во время матча.'] },
    multiplayer: { title: '3. Сетевая игра: создание комнаты и приглашение друзей', intro: 'Экран комнаты зависит от игры. Следуйте подсказкам внутри выбранной игры.', steps: ['Откройте GAMES, выберите игру с сетевым режимом и нажмите Multiplayer. В Street Gang Star сначала откройте игровой центр.', 'Чтобы создать закрытую комнату, нажмите Create Room и подождите. Код появится в комнате или в заголовке игры.', 'Скопируйте код, если доступна такая кнопка, и отправьте его другу в Telegram целиком. Убедитесь, что это код нужной игры.', 'Друг должен открыть ту же игру, выбрать Multiplayer, ввести или вставить код в поле Join и нажать JOIN. Удалите случайные пробелы.', 'В Street Dice хозяин видит участников и, если доступно, может добавить ИИ-игрока. Игроки нажимают Ready, а хозяин начинает матч, когда все готовы.', 'В Street Gang Star друзья входят в частную комнату по точному коду. Random City Match — другой режим.', 'Дождитесь подтверждения входа или появления друга в комнате. Отправка кода не означает, что он уже присоединился.', 'Если комната заполнена, истекла или закрыта, создайте новую и отправьте новый код.'] },
    rejoin: { title: '4. Потеря соединения и повторный вход', intro: 'Код не гарантирует, что комната будет доступна постоянно. Повторный вход зависит от игры и активности комнаты.', steps: ['Проверьте интернет, вернитесь в ту же игру и снова откройте Multiplayer.', 'Если есть кнопка Rejoin или Continue, используйте её. Street Dice может сохранить данные комнаты на устройстве и восстановить её.', 'Если комната не восстановилась, спросите хозяина, открыта ли она, и попросите актуальный код.', 'Если код не принимается, проверьте буквы и цифры, выбранную игру и уточните, не заполнена ли комната и не завершена ли игра.', 'Если хозяин вышел или комната закрыта, создайте новую и пригласите игроков снова.', 'Если экран завис, подождите, нажмите Back и откройте режим заново. При необходимости перезапустите Telegram Mini App.', 'Не нажимайте Create Room много раз, пока обрабатывается первый запрос.'] },
    controls: { title: '5. Управление, цели и завершение матча', intro: 'Управление зависит от игры и устройства. Перед началом прочитайте подсказки на экране.', steps: ['На телефоне используйте виртуальный джойстик, стрелки или кнопки действий. Отпустите палец, чтобы остановиться.', 'В Street Gang Star джойстик перемещает персонажа. Используйте доступные кнопки стрельбы, прыжка, перезарядки, укрытия, бега и вождения.', 'В гонках и играх на мотоцикле используйте экранные кнопки поворота, ускорения и торможения. Следите за целью и таймером.', 'В Street Dice бросайте кубики по очереди и выбирайте фишку, когда игра разрешает ход.', 'В других мини-играх читайте их правила. Управление одной игры может не работать в другой.', 'После раунда прочитайте результат и сообщение о награде. Если награда не появилась, проверьте баланс и историю операций, прежде чем повторять действие.'] },
    coins: { title: '6. Street Coins, награды и ежедневные задания', intro: 'Street Coins — внутриигровая валюта. Размер и условия получения награды зависят от активности и правил раздела.', steps: ['Проверьте баланс на Home и откройте историю транзакций.', 'Откройте WATCH & EARN, нажмите просмотр и дождитесь окончания рекламного видео. Пропущенная, недоступная или неудачно загруженная реклама не даёт права на награду.', 'У ежедневных наград и заданий свои требования. Прочитайте их и проверьте статус перед Claim.', 'Для некоторых действий действуют дневные лимиты, ожидание или условия участия. Следуйте сообщению на экране.', 'Не считайте, что каждая игра, задача, публикация или видео приносит монеты. Учитывайте только подтверждённые приложением награды.'] },
    tasks: { title: '7. TASKS: выполнение заданий и отправка на проверку', intro: 'Некоторые задания требуют выполнить действие вне игры и отправить подтверждение. Выполнение и отправка доказательства — разные шаги.', steps: ['Откройте TASKS на Home или в Quick Hustle Hub. Прочитайте инструкции, награду, ограничения и требования к подтверждению.', 'Нажмите кнопку задания и выполните действие: вступите в официальный канал или группу, подпишитесь на аккаунт, пригласите друга, достигните цели или разместите рекламу.', 'Вернитесь к заданию и подготовьте требуемые доказательства. Сделайте чёткий снимок экрана; для видео предоставьте публичную ссылку и снимки просмотров или отметок «Нравится», если их запросили.', 'Если есть подготовительный шаг, нажмите указанную кнопку. Затем она может измениться на Submit for review.', 'Нажмите Submit for review один раз и дождитесь подтверждения. Не нажимайте повторно во время отправки.', 'Для задания со статусом сначала загрузите снимок публикации, затем отправьте подтверждение. Соблюдайте дневной лимит.', 'Для продвижения видео используйте только платформы, указанные в инструкции, например TikTok, YouTube или Facebook. Отправьте ссылку и требуемые снимки.', 'Pending Review означает, что проверка продолжается. Approved или Verified — принято. Rejected — отклонено: прочитайте причину и исправьте доказательство, если это разрешено.', 'Не отправляйте одно задание повторно, пока оно ожидает проверки. Некоторые награды начисляются после проверки сервера и одобрения администратора.'] },
    studio: { title: '8. STUDIO: запись аудио-фристайла', intro: 'В Studio можно выбрать бит, записать голос, прослушать микс и опубликовать его. Некоторые функции требуют активной аренды Studio или открытого уровня.', steps: ['Откройте STUDIO на нижней панели. Проверьте, активен ли доступ или аренда.', 'Выберите бит и нажмите Preview или Play для прослушивания. Некоторые биты доступны на более высоких уровнях.', 'Настройте Beat Volume и Voice Volume, чтобы сбалансировать музыку и голос.', 'Разрешите доступ к микрофону, когда телефон запросит его. Если разрешение отклонено, включите его в настройках устройства или браузера.', 'Нажмите Record и запишите фристайл в пределах показанной минимальной и максимальной длительности. Нажмите Stop.', 'Нажмите Preview Mix и прослушайте запись. При необходимости запишите заново, если дневной лимит не исчерпан.', 'Когда всё готово, нажмите Post Mix или Post и дождитесь сообщения об успехе или ошибке.', 'Лимиты аудио- и видеозаписи могут быть общими и зависеть от уровня Studio. Проверьте счётчик.'] },
    video: { title: '9. STUDIO: запись видео-фристайла', intro: 'Video Freestyle использует камеру телефона. Telegram требуется разрешение на камеру и микрофон.', steps: ['Откройте STUDIO, затем Video Freestyle. При запросе нажмите Enable Camera.', 'Если iPhone или Telegram запрашивает доступ к камере или микрофону, выберите Allow. Если доступ ранее запрещён, измените разрешение в настройках устройства.', 'Используйте Flip для переключения передней и задней камеры, если устройство это поддерживает. Во время записи переключение может быть недоступно.', 'Выберите фильтр: Normal, Warm, B&W, Cool или Vintage. Прокрутите экран, чтобы увидеть все элементы управления; кнопки действий находятся над фильтрами.', 'Нажмите Record для начала и Stop для завершения. Используйте Preview перед публикацией.', 'Нажмите Post, когда будете довольны результатом, и дождитесь подтверждения. При ошибке загрузки проверьте интернет.', 'Нажмите Close для выхода. Не закрывайте камеру во время записи.'] },
    shop: { title: '10. SHOP, инвентарь, улучшения и предметы', intro: 'Откройте SHOP на нижней панели, чтобы просмотреть предметы и улучшения. Категории могут включать одежду, дома, транспорт, телефоны, еду и улучшения Studio.', steps: ['Выберите категорию и предмет, чтобы увидеть описание и цену. Перед покупкой проверьте стоимость в Street Coins.', 'Нажмите Buy или кнопку покупки и дождитесь подтверждения. Не нажимайте повторно, пока обновляется баланс.', 'Купленные предметы можно надеть через карточку или инвентарь. Владение предметом не означает, что он надет: выберите Equip.', 'Некоторые предметы расходуются, арендуются, покупаются навсегда или являются улучшениями. Прочитайте описание и срок действия.', 'Если монет не хватает, заработайте их в доступных активностях или выберите более доступный предмет.'] },
    bank: { title: '11. BANK, кошелёк, обмен и вывод средств', intro: 'В BANK могут отображаться баланс, конвертер, вывод средств, история и другие разделы. Условия могут меняться.', steps: ['Откройте BANK через ярлыки Home. Используйте вкладки для просмотра баланса, конвертера, вывода и истории.', 'Перед обменом проверьте выбранную валюту, курс и сумму в подтверждении.', 'Перед запросом вывода прочитайте минимальную сумму, поддерживаемый способ, сеть, инструкции по адресу кошелька, дату доступности и статус.', 'Указывайте только принадлежащий вам адрес, соответствующий выбранной сети или способу. Неверный адрес или сеть могут привести к потере средств.', 'Отправленный запрос не означает, что платёж завершён. Проверьте историю и статус. Ожидающий запрос — это ещё не полученные деньги.'] },
    profile: { title: '12. PROFILE, приглашения, язык и поддержка', intro: 'В профиле отображаются ваша учётная запись Telegram, данные игрока, настройки и помощь.', steps: ['Откройте PROFILE на нижней панели. Убедитесь, что имя Telegram и данные принадлежат вам.', 'Скопируйте личный код приглашения или реферальную ссылку и поделитесь ею с другом.', 'Откройте Settings, чтобы изменить доступные настройки, включая язык. Выберите Русский, чтобы видеть доступный перевод.', 'Если нужна помощь, откройте Support. Укажите экран, кнопку, ожидаемый результат и то, что произошло.', 'Защищайте аккаунт Telegram. Не сообщайте коды входа, пароли, приватные ключи или фразу восстановления кошелька.'] },
    troubleshoot: { title: '13. Частые проблемы и решения', intro: 'Попробуйте эти действия, прежде чем повторять покупку, отправку или действие с комнатой.', steps: ['Кнопка не отвечает: подождите несколько секунд, проверьте интернет, прокрутите экран так, чтобы кнопка была видна полностью, и попробуйте ещё раз.', 'Игра не загружается: вернитесь в GAMES, откройте игру снова, при необходимости перезапустите Telegram Mini App.', 'Друг не может войти: убедитесь, что вы открыли одну и ту же игру, проверьте каждый символ кода и спросите хозяина, активна ли комната.', 'Комната потеряна: используйте Rejoin, если доступно. Иначе попросите актуальный код или создайте новую комнату.', 'Камера или микрофон не работают: проверьте разрешения Telegram/iPhone, закройте другие приложения с камерой и снова откройте Studio.', 'Задание ожидает проверки: дождитесь проверки и позже посмотрите статус. Не отправляйте дубликаты.', 'Награда или покупка непонятна: проверьте баланс и историю, затем обратитесь в Support, указав экран и примерное время. Не сообщайте секретные данные.'] },
    fairplay: { title: '14. Играйте честно и защищайте аккаунт', intro: 'Помогайте сохранять Street Life интересной игрой и защищайте свой прогресс.', steps: ['Не используйте читы, не эксплуатируйте ошибки, не выдавайте себя за другого игрока и не преследуйте людей в комнатах или чатах.', 'Делитесь кодами комнат только с приглашёнными людьми. Не публикуйте личную информацию в открытых чатах.', 'Следуйте только официальным инструкциям приложения о наградах, заданиях и платежах. Никто не должен просить код входа Telegram или фразу восстановления кошелька.', 'Если что-то выглядит неправильно, остановитесь и обратитесь в Support, а не пытайтесь использовать проблему.'] }
  },
  id: {
    start: { title: '1. Mulai di sini: kenali layar Beranda', intro: 'Layar Beranda adalah dasbor utama. Gulir ke atas dan ke bawah untuk melihat seluruh halaman.', steps: ['Saldo Street Coins terlihat di bagian atas. Ketuk saldo atau pintasan transaksi untuk memeriksa aktivitas koin.', 'Gunakan Quick Hustle Hub dan navigasi bawah untuk membuka berbagai bagian Street Life.', 'HOME kembali ke beranda, GAMES membuka pustaka game, STUDIO membuka alat freestyle, SHOP menampilkan item dan peningkatan, TOUGH WAR membuka area perang, dan PROFILE berisi data serta pengaturan pemain.', 'Pintasan lain dapat membuka TASKS, WATCH & EARN, BANK, dan inventaris. Perhatikan judul setiap layar.', 'Jika layar tampak terpotong, gulir di dalam halaman. Pada layar yang didukung, tombol ikon mata menyembunyikan atau menampilkan bilah navigasi.'] },
    games: { title: '2. Pilih game dan pahami mode permainan', intro: 'Buka GAMES dari navigasi bawah. Pilih kategori, lalu ketuk kartu game yang diinginkan.', steps: ['Street Gang Star: buka pusat game lalu pilih Single Player atau Multiplayer. Dalam multiplayer, buat ruang dengan kode, bergabung memakai kode, atau gunakan Random City Match jika tersedia.', 'Street Race: pilih balapan, baca petunjuk, lalu gunakan kontrol mengemudi di layar. Hindari lalu lintas dan rintangan serta kumpulkan koin jika tersedia.', 'Street Rider Delivery: ikuti tujuan pengantaran dan penghitung waktu. Gunakan kontrol motor untuk mencapai tujuan.', 'Street Dice: pilih Single Player atau Multiplayer. Host membuat ruang dan membagikan kodenya; pemain lain memasukkan kode untuk bergabung.', 'Mini-game lain dapat mencakup Turf War, Street Crush, Street Slot, dan Street Flip. Setiap game memiliki aturan dan kontrol sendiri.', 'Game bertanda Coming Soon belum dapat dimainkan.', 'Gunakan Back di dalam game untuk kembali ke daftar. Jangan tutup Telegram saat pertandingan berlangsung.'] },
    multiplayer: { title: '3. Multiplayer: buat ruang dan undang teman', intro: 'Tampilan lobi berbeda untuk setiap game. Ikuti kontrol ruang yang ditampilkan di game pilihan.', steps: ['Buka GAMES, pilih game yang mendukung multiplayer, lalu ketuk Multiplayer. Di Street Gang Star, buka pusat game terlebih dahulu.', 'Untuk membuat ruang privat, ketuk Create Room dan tunggu. Kode ruang akan muncul di lobi atau bagian atas game.', 'Salin kode jika tombol tersedia dan kirim kode lengkap kepada teman melalui Telegram. Pastikan kode untuk game yang benar.', 'Teman harus membuka game yang sama, memilih Multiplayer, mengetik atau menempel kode di kolom Join, lalu mengetuk JOIN. Hapus spasi yang tidak sengaja.', 'Di Street Dice, host dapat melihat pemain dan, jika tersedia, menambahkan pemain AI. Pemain mengetuk Ready; host memulai saat semua siap.', 'Di Street Gang Star, teman masuk ke ruang privat dengan kode yang tepat. Random City Match adalah pilihan yang berbeda.', 'Tunggu konfirmasi bergabung atau sampai pemain lain terlihat di lobi. Mengirim kode bukan berarti teman sudah masuk.', 'Jika ruang penuh, kedaluwarsa, atau selesai, buat ruang baru dan bagikan kode baru.'] },
    rejoin: { title: '4. Terputus, gagal bergabung, atau masuk kembali', intro: 'Kode ruang tidak menjamin ruang selalu tersedia. Fitur masuk kembali bergantung pada game dan apakah ruang masih aktif.', steps: ['Periksa koneksi internet, buka kembali game yang sama, lalu masuk ke Multiplayer.', 'Jika tersedia Rejoin atau Continue, gunakan opsi itu. Street Dice dapat menyimpan informasi ruang di perangkat dan memulihkannya saat dibuka kembali.', 'Jika ruang tidak pulih, tanyakan kepada host apakah ruang masih terbuka dan minta kode terbaru.', 'Jika kode ditolak, periksa huruf dan angka, pastikan game yang dipilih sama, lalu tanyakan apakah ruang penuh atau sudah berakhir.', 'Jika host keluar atau ruang ditutup, buat ruang baru dan undang pemain lagi.', 'Jika layar macet, tunggu sebentar, gunakan Back, lalu buka mode lagi. Jika perlu, tutup dan buka kembali Telegram Mini App.', 'Jangan mengetuk Create Room berulang kali saat permintaan pertama masih diproses.'] },
    controls: { title: '5. Kontrol, tujuan, dan mengakhiri pertandingan', intro: 'Kontrol bergantung pada game dan perangkat. Baca petunjuk kontrol sebelum mulai.', steps: ['Di ponsel, gunakan joystick virtual, tombol arah, atau tombol aksi. Lepaskan jari untuk berhenti.', 'Di Street Gang Star, joystick menggerakkan karakter. Gunakan tombol tembak, lompat, isi ulang, berlindung, lari, dan mengemudi jika tersedia.', 'Dalam game balap dan motor, gunakan kontrol layar untuk berbelok, mempercepat, atau mengerem. Ikuti tujuan dan timer.', 'Di Street Dice, lempar dadu sesuai giliran dan pilih pion saat game mengizinkan langkah.', 'Baca aturan masing-masing mini-game. Kontrol dari satu game belum tentu berlaku di game lain.', 'Saat ronde selesai, baca hasil dan pesan hadiah. Jika hadiah tidak muncul, periksa saldo dan riwayat transaksi sebelum mengulangi tindakan.'] },
    coins: { title: '6. Street Coins, hadiah, dan aktivitas harian', intro: 'Street Coins adalah mata uang dalam game. Jumlah dan kelayakan hadiah bergantung pada aktivitas dan aturan yang ditampilkan.', steps: ['Periksa saldo Street Coins di Home. Buka riwayat transaksi untuk melihat aktivitas yang tercatat.', 'Buka WATCH & EARN, ketuk tombol tonton, dan biarkan video sponsor selesai. Iklan yang dilewati, gagal, atau tidak tersedia tidak memenuhi syarat hadiah.', 'Hadiah harian dan hadiah tugas memiliki persyaratan masing-masing. Baca persyaratan dan status sebelum mengetuk Claim.', 'Beberapa aktivitas memiliki batas harian, waktu tunggu, atau syarat kelayakan. Ikuti informasi yang muncul di layar.', 'Jangan menganggap setiap game, video, tugas, atau posting Studio memberi koin. Hanya andalkan hadiah yang dikonfirmasi aplikasi.'] },
    tasks: { title: '7. TASKS: selesaikan aktivitas dan kirim untuk ditinjau', intro: 'Beberapa tugas meminta aktivitas di luar game lalu bukti untuk diverifikasi. Menyelesaikan aktivitas dan mengirim bukti adalah dua langkah berbeda.', steps: ['Buka TASKS dari Home atau Quick Hustle Hub. Baca instruksi lengkap, hadiah, batas, dan persyaratan bukti.', 'Ketuk tombol tugas dan lakukan aktivitas yang diminta, seperti bergabung ke kanal atau grup resmi, mengikuti akun, mengundang teman, mencapai target game, atau memposting promosi.', 'Kembali ke tugas yang sama. Siapkan bukti yang diminta: tangkapan layar yang jelas; untuk promosi video, tautan publik dan tangkapan layar jumlah tayangan atau suka jika diminta.', 'Jika ada langkah persiapan, ketuk tombol yang ditunjukkan. Tombol dapat berubah menjadi Submit for review.', 'Ketuk Submit for review satu kali dan tunggu konfirmasi. Jangan mengetuk berulang kali saat pengiriman diproses.', 'Untuk tugas Status, unggah tangkapan layar posting terlebih dahulu, lalu kirim bukti. Patuhi batas posting harian.', 'Untuk promosi video, gunakan hanya platform yang diterima dalam instruksi, seperti TikTok, YouTube, atau Facebook. Kirim tautan dan bukti yang diminta.', 'Pending Review berarti masih diperiksa. Approved atau Verified berarti diterima. Rejected berarti ditolak: baca alasannya dan perbaiki bukti jika diizinkan.', 'Jangan mengirim tugas yang sama berulang kali saat masih menunggu. Beberapa hadiah diberikan setelah verifikasi server dan persetujuan admin.'] },
    studio: { title: '8. STUDIO: rekam freestyle audio', intro: 'Studio memungkinkan Anda memilih beat, merekam suara, mendengarkan hasil, dan memposting mix. Beberapa fitur memerlukan sewa Studio aktif atau level terbuka.', steps: ['Buka STUDIO dari navigasi bawah. Periksa apakah akses atau sewa Studio aktif.', 'Jelajahi daftar beat. Ketuk beat untuk memilih, lalu gunakan Preview atau Play untuk mendengarkan. Beberapa beat memerlukan level lebih tinggi.', 'Atur Beat Volume dan Voice Volume untuk menyeimbangkan musik dan suara.', 'Izinkan akses mikrofon saat ponsel meminta. Jika ditolak, rekaman mungkin tidak berfungsi; aktifkan izin di pengaturan perangkat atau browser.', 'Ketuk Record dan rekam freestyle sesuai durasi minimum dan maksimum yang ditampilkan. Ketuk Stop untuk selesai.', 'Ketuk Preview Mix untuk mendengarkan. Jika belum puas, rekam ulang jika jatah harian masih tersedia.', 'Jika sudah puas, ketuk Post Mix atau Post dan tunggu pesan berhasil atau gagal.', 'Batas rekaman audio dan video dapat digabung dan bergantung pada level Studio. Periksa penghitung di layar.'] },
    video: { title: '9. STUDIO: rekam freestyle video', intro: 'Video Freestyle menggunakan kamera ponsel. Telegram memerlukan izin kamera dan mikrofon.', steps: ['Buka STUDIO lalu Video Freestyle. Ketuk Enable Camera saat diminta.', 'Jika iPhone atau Telegram meminta izin kamera atau mikrofon, pilih Allow. Jika sebelumnya diblokir, ubah izin di pengaturan perangkat.', 'Gunakan Flip untuk beralih kamera depan dan belakang jika perangkat mendukungnya. Peralihan mungkin tidak tersedia saat merekam.', 'Pilih filter Normal, Warm, B&W, Cool, atau Vintage. Gulir layar untuk melihat semua kontrol; tombol aksi berada di atas filter.', 'Ketuk Record untuk mulai dan Stop untuk selesai. Gunakan Preview untuk menonton sebelum memposting.', 'Ketuk Post setelah puas dan tunggu konfirmasi. Jika unggahan gagal, periksa koneksi.', 'Ketuk Close untuk keluar. Jangan tutup kamera saat rekaman berlangsung.'] },
    shop: { title: '10. SHOP, inventaris, peningkatan, dan item', intro: 'Buka SHOP dari navigasi bawah untuk melihat item dan peningkatan. Kategori dapat mencakup pakaian, rumah, kendaraan, ponsel, makanan, dan peningkatan Studio.', steps: ['Ketuk kategori dan pilih item untuk melihat detail serta harga. Periksa biaya Street Coins sebelum membeli.', 'Ketuk Buy atau tombol pembelian dan tunggu konfirmasi. Jangan mengetuk berulang kali saat saldo diperbarui.', 'Item yang dimiliki dapat dipakai melalui kartu item atau inventaris. Memiliki item belum berarti item sudah dipakai; pilih Equip.', 'Beberapa item bersifat habis pakai, sewaan, permanen, atau peningkatan. Baca deskripsi dan masa berlakunya.', 'Jika saldo tidak cukup, dapatkan Street Coins melalui aktivitas yang memenuhi syarat atau pilih item yang lebih murah.'] },
    bank: { title: '11. BANK, dompet, konversi, dan penarikan', intro: 'BANK dapat menampilkan saldo, konverter, penarikan, riwayat, dan bagian lain. Ketersediaan serta persyaratan dapat berubah.', steps: ['Buka BANK dari pintasan Home. Gunakan tab untuk melihat saldo, konverter, penarikan, dan riwayat.', 'Sebelum mengonversi koin, periksa mata uang, kurs, dan jumlah pada konfirmasi.', 'Sebelum meminta penarikan, baca jumlah minimum, metode yang didukung, jaringan, petunjuk alamat dompet, tanggal ketersediaan, dan status.', 'Masukkan hanya alamat milik Anda yang sesuai dengan jaringan atau metode pilihan. Alamat atau jaringan yang salah dapat menyebabkan dana hilang.', 'Permintaan yang dikirim belum berarti pembayaran selesai. Periksa riwayat dan status; permintaan tertunda bukan uang yang sudah diterima.'] },
    profile: { title: '12. PROFILE, undangan, bahasa, dan dukungan', intro: 'Profil menampilkan identitas Telegram, informasi pemain, pengaturan, dan opsi bantuan.', steps: ['Buka PROFILE dari navigasi bawah. Pastikan nama Telegram dan informasi akun yang ditampilkan adalah milik Anda.', 'Gunakan kode undangan atau tautan referral untuk menyalin undangan pribadi dan membagikannya kepada teman.', 'Buka Settings untuk mengubah preferensi aplikasi yang tersedia, termasuk bahasa. Pilih Bahasa Indonesia untuk melihat terjemahan yang tersedia.', 'Gunakan Support jika membutuhkan bantuan. Jelaskan layar dan tombol yang digunakan, apa yang diharapkan, dan apa yang terjadi.', 'Amankan akun Telegram. Jangan bagikan kode login, kata sandi, kunci privat dompet, atau frasa pemulihan.'] },
    troubleshoot: { title: '13. Masalah umum dan cara mengatasinya', intro: 'Coba langkah berikut sebelum mengulangi pembelian, pengiriman, atau tindakan ruang.', steps: ['Tombol tidak merespons: tunggu beberapa detik, periksa koneksi, gulir agar tombol terlihat penuh, lalu coba sekali lagi.', 'Game tidak dimuat: kembali ke GAMES, buka lagi, dan jika perlu tutup lalu buka Telegram Mini App.', 'Teman tidak bisa bergabung: pastikan kedua pemain membuka game yang sama, periksa setiap karakter kode, dan tanyakan kepada host apakah ruang masih aktif.', 'Ruang hilang: gunakan Rejoin jika tersedia. Jika tidak, minta kode terbaru dari host atau buat ruang baru.', 'Kamera atau mikrofon tidak berfungsi: periksa izin Telegram/iPhone, tutup aplikasi lain yang memakai kamera, lalu buka Studio lagi.', 'Tugas masih tertunda: tunggu peninjauan dan periksa status nanti. Jangan kirim duplikat.', 'Hadiah atau pembelian tidak jelas: periksa saldo dan riwayat, lalu hubungi Support dengan nama layar dan perkiraan waktu. Jangan bagikan rahasia.'] },
    fairplay: { title: '14. Bermain adil dan lindungi akun', intro: 'Bantu menjaga Street Life tetap menyenangkan dan lindungi progres Anda.', steps: ['Jangan curang, mengeksploitasi bug, menyamar sebagai pemain lain, atau melecehkan orang di ruang maupun obrolan.', 'Bagikan kode ruang hanya kepada orang yang ingin Anda undang. Jangan memposting informasi pribadi di obrolan publik.', 'Ikuti hanya petunjuk resmi aplikasi untuk hadiah, tugas, dan pembayaran. Jangan berikan kode login Telegram atau frasa pemulihan dompet kepada siapa pun.', 'Jika ada sesuatu yang tampak salah, berhenti dan hubungi Support, bukan mencoba mengeksploitasi masalah.'] }
  },
  pcm: {
    start: { title: '1. Start here: know your Home screen', intro: 'Home screen na your main dashboard. Scroll up and down make you see everything for the page.', steps: ['Your Street Coins balance dey near the top. Tap am or the transaction shortcut to check your coin activity.', 'Use Quick Hustle Hub and the bottom navigation to open different parts of Street Life.', 'HOME go take you back home. GAMES open game library. STUDIO open freestyle tools. SHOP show items and upgrades. TOUGH WAR open war area. PROFILE get your player details and settings.', 'Other shortcuts fit open TASKS, WATCH & EARN, BANK and your inventory. Read each screen title make you know where you dey.', 'If screen look cut, scroll inside the page. For supported screens, eye button fit hide or show the navigation bars.'] },
    games: { title: '2. Choose game and understand game modes', intro: 'Open GAMES from bottom navigation. Choose category, then tap the game wey you wan play.', steps: ['Street Gang Star: enter the game hub and choose Single Player or Multiplayer. For multiplayer, create room with code, join with code, or use Random City Match when e dey available.', 'Street Race: choose race, read the instructions and use the driving controls wey show for screen. Avoid traffic and obstacles; collect coins if dem dey.', 'Street Rider Delivery: follow the delivery target and timer. Use the bike controls reach where dem send you go.', 'Street Dice: choose Single Player or Multiplayer. Host go create room and share the code; other players go enter the code to join.', 'Other mini-games fit include Turf War, Street Crush, Street Slot and Street Flip. Every game get im own rules and controls.', 'If game show Coming Soon, e never ready to play.', 'Use Back inside the game to return to game list. No close Telegram while match still dey go.'] },
    multiplayer: { title: '3. Multiplayer: create room and invite your friends', intro: 'Room screen fit different for each game. Follow the room controls wey show inside the game.', steps: ['Open GAMES, choose game wey support multiplayer and tap Multiplayer. For Street Gang Star, open the game hub first.', 'To host private room, tap Create Room and wait. The room code go show for lobby or game header.', 'Copy the code if copy button dey, then send the full code give your friend for Telegram. Make sure say na the correct game code.', 'Your friend must open the same game, choose Multiplayer, type or paste the code for Join box and tap JOIN. Remove any extra space.', 'For Street Dice, host fit see players and fit add AI player if the option dey. Players tap Ready; host start when everybody ready.', 'For Street Gang Star, friends use the exact code enter private room. Random City Match na different option.', 'Wait make game confirm say you don join or make the other player show for lobby. Sending code no mean say person don enter.', 'If room full, expire or finish, create another room and share the new code.'] },
    rejoin: { title: '4. If network cut or you need enter room again', intro: 'Room code no mean say the room go dey open forever. Rejoin depend on the game and whether the room still dey active.', steps: ['Check your internet first. Return to the same game and open Multiplayer again.', 'If Rejoin or Continue show, use am. Street Dice fit save room information for your device and restore am when you open multiplayer again.', 'If room no come back, ask the host whether e still dey open and request the current code.', 'If code no work, check letters and numbers, confirm say na the same game, and ask whether room don full or finish.', 'If host don comot or room don close, create new room and invite everybody again.', 'If screen freeze, wait small, tap Back inside the game and open the mode again. If e continue, close and reopen Telegram Mini App.', 'No tap Create Room plenty times while the first request still dey process.'] },
    controls: { title: '5. Controls, objectives and how match take end', intro: 'Controls depend on the game and device. Read the instructions wey show before you start.', steps: ['For phone, use virtual joystick, direction buttons or action buttons. Remove your finger when you wan stop.', 'For Street Gang Star, joystick move your character. Use the available shoot, jump, reload, cover, run and driving buttons.', 'For racing and bike games, use screen controls to turn, accelerate or brake. Follow the mission target and timer.', 'For Street Dice, roll dice when na your turn and choose a token when game allow you move.', 'For other mini-games, read their own rules. Control for one game fit no work for another.', 'When round finish, read result and reward message. If reward no show, check balance and transaction history before you try the same thing again.'] },
    coins: { title: '6. Street Coins, rewards and daily activities', intro: 'Street Coins na the game money inside the app. Reward amount and who qualify depend on the activity rules.', steps: ['Check your Street Coins balance for Home. Open transaction history to see recorded activity.', 'Open WATCH & EARN, tap watch button and allow the sponsored video finish. If you skip am, video fail or e no dey available, you no qualify for the reward.', 'Daily rewards and task rewards get their own requirements. Read am and check status before you tap Claim.', 'Some activities get daily limit, waiting time or eligibility rules. Follow the message wey show for screen.', 'No assume say every game, video, task or Studio post go give coins. Trust only reward wey the app confirm.'] },
    tasks: { title: '7. TASKS: do activity and send am for review', intro: 'Some tasks need you do something outside the game and send proof make dem verify am. Doing the activity and sending proof na two different steps.', steps: ['Open TASKS from Home or Quick Hustle Hub. Read the full instructions, reward, limits and proof wey dem need.', 'Tap the task button and do wetin dem ask: join official channel or group, follow account, invite friend, reach game target or post promotion.', 'Return to the same task. Prepare the exact proof dem request. Take clear screenshot; for video promotion, send public video link and screenshot of views or likes if dem ask.', 'If task get preparation step, tap the button. E fit change to Submit for review after that.', 'Tap Submit for review one time and wait for confirmation. No tap am again and again while e dey process.', 'For Status promotion task, upload screenshot of the status post first, then submit the proof. Follow the daily posting limit.', 'For video promotion, use only platforms wey the instructions accept, like TikTok, YouTube or Facebook. Send the link and proof screenshots dem request.', 'Pending Review mean say dem never finish checking. Approved or Verified mean dem accept am. Rejected mean dem reject am: read the reason and correct proof if dem allow.', 'No submit the same task plenty times while e still dey pending. Some rewards enter after server verification and admin approval.'] },
    studio: { title: '8. STUDIO: record audio freestyle', intro: 'Studio let you choose beat, record your voice, listen to the mix and post am. Some features need active Studio rent or unlocked level.', steps: ['Open STUDIO from bottom navigation. Check whether your Studio access or rent dey active.', 'Browse beats, tap one to select am, then use Preview or Play listen before recording. Some beats need higher level.', 'Adjust Beat Volume and Voice Volume make music and your voice balance well.', 'Allow microphone when your phone ask. If you no allow am, recording fit no work; enable microphone for device or browser settings.', 'Tap Record and do your freestyle. Follow the minimum and maximum time wey show. Tap Stop when you finish.', 'Tap Preview Mix listen. If you no like am, record again if you still get daily recording left.', 'When you don okay with am, tap Post Mix or Post and wait for success or error message.', 'Audio and video recording fit share daily limit, and Studio level fit affect am. Check the counter for screen.'] },
    video: { title: '9. STUDIO: record video freestyle', intro: 'Video Freestyle use your phone camera. Telegram need permission for camera and microphone.', steps: ['Open STUDIO and enter Video Freestyle. Tap Enable Camera when e ask.', 'If iPhone or Telegram ask camera or microphone permission, choose Allow. If you block am before, change the permission for device settings.', 'Use Flip switch front and back camera if your device support am. You fit no switch camera while recording.', 'Choose filter: Normal, Warm, B&W, Cool or Vintage. Scroll the camera screen to see all controls; action buttons dey above filters.', 'Tap Record start and Stop finish. Use Preview watch the video before posting.', 'Tap Post when you like the result and wait for confirmation. If upload fail, check your network.', 'Tap Close comot. No close camera while recording still dey go.'] },
    shop: { title: '10. SHOP, inventory, upgrades and your items', intro: 'Open SHOP from bottom navigation to see items and upgrades. Categories fit include clothes, houses, vehicles, phones, food and Studio upgrades.', steps: ['Tap category and choose item to see details and price. Check Street Coins cost before buying.', 'Tap Buy or purchase button and wait for confirmation. No tap am plenty times while balance dey update.', 'You fit equip items from item card or inventory. To own item no mean say you don wear am; choose Equip.', 'Some items na consumables, rentals, permanent items or upgrades. Read description and expiry details before you confirm.', 'If your coins no reach, earn more through eligible activities or choose item wey your balance fit buy.'] },
    bank: { title: '11. BANK, wallet, conversion and withdrawal', intro: 'BANK fit show balance, converter, withdrawal, history and other sections. Availability and requirements fit change.', steps: ['Open BANK from Home shortcuts. Use tabs check balance, converter, withdrawal and history.', 'Before you convert coins, check the currency, rate and amount wey confirmation show.', 'Before withdrawal request, read minimum amount, supported method, network, wallet address instructions, available date and status.', 'Enter only address wey belong to you and match the network or method. Wrong address or network fit make you lose funds.', 'Sending request no mean say payment don complete. Check withdrawal history and status. Pending request no be money wey you don receive.'] },
    profile: { title: '12. PROFILE, invite links, language and support', intro: 'Your Profile show your Telegram identity, player information, settings and help options.', steps: ['Open PROFILE from bottom navigation. Confirm say the Telegram name and account information na your own.', 'Use invite code or referral link to copy your personal invite and share am with friend.', 'Open Settings change available preferences, including language. Choose Nigerian Pidgin to see the available translation.', 'Use Support when you need help. Explain the screen and button wey you use, wetin you expect and wetin happen.', 'Protect your Telegram account. No share login codes, passwords, private wallet keys or recovery phrase.'] },
    troubleshoot: { title: '13. Common problems and wetin you fit do', intro: 'Try these steps before you repeat purchase, submission or room action.', steps: ['Button no dey respond: wait small, check internet, scroll make button show complete, then try one more time.', 'Game no load: return to GAMES, open am again, and if e need, close and reopen Telegram Mini App.', 'Your friend no fit join: confirm say both of una open the same game, check every character for code and ask host whether room still dey active.', 'Room don lost: use Rejoin if e show. If no, ask host for current code or create new room.', 'Camera or microphone no work: check Telegram/iPhone permissions, close other apps wey dey use camera, then open Studio again.', 'Task dey pending: wait for review and check status later. No send duplicate.', 'Reward or purchase no clear: check balance and history, then contact Support with screen name and approximate time. No send secret information.'] },
    fairplay: { title: '14. Play fair and protect your account', intro: 'Help make Street Life enjoyable and protect your progress.', steps: ['No cheat, exploit bugs, pretend to be another player or harass people for rooms and chats.', 'Share room codes only with people wey you wan invite. No post private information for public chats.', 'Follow only official app instructions for rewards, tasks and payments. Nobody suppose ask for your Telegram login code or wallet recovery phrase.', 'If something no look correct, stop and contact Support instead of trying to exploit the problem.'] }
  }
};

export function getHowToPlayTranslation(language: LanguageCode, chapterId: string) {
  return howToPlayTranslations[language]?.[chapterId];
}
